export const GetAiInsightsResponseItem = zod.object({
  "id": zod.string(),
  "type": zod.enum(['sales_trend', 'inventory_alert', 'revenue_change', 'product_performance', 'opportunity']),
  "title": zod.string(),
  "description": zod.string(),
  "severity": zod.enum(['info', 'warning', 'success', 'alert']),
  "metric": zod.string().nullish(),
  "change": zod.number().nullish()
})
export const GetAiInsightsResponse = zod.array(GetAiInsightsResponseItem)


/**
 * @summary Get AI sales forecast
 */
export const GetAiForecastResponse = zod.object({
  "nextWeekRevenue": zod.number(),
  "nextMonthRevenue": zod.number(),
  "confidence": zod.number(),
  "forecastPoints": zod.array(zod.object({
  "date": zod.string(),
  "revenue": zod.number(),
  "sales": zod.number()
})),
  "seasonalTrends": zod.array(zod.string()).optional()
})


/**
 * @summary Get slow-moving product analysis
 */
export const GetSlowMovingProductsResponseItem = zod.object({
  "productId": zod.number(),
  "productName": zod.string(),
  "sku": zod.string().optional(),
  "daysSinceLastSale": zod.number(),
  "currentStock": zod.number(),
  "stockValue": zod.number().optional(),
  "recommendation": zod.enum(['discount', 'bundle', 'promote', 'clearance']),
  "suggestedDiscount": zod.number().nullish()
})
export const GetSlowMovingProductsResponse = zod.array(GetSlowMovingProductsResponseItem)


/**
 * @summary AI business assistant chat
 */
export const AiChatBody = zod.object({
  "message": zod.string(),
  "conversationHistory": zod.array(zod.object({
  "role": zod.enum(['user', 'assistant']),
  "content": zod.string()
})).optional()
})

export const AiChatResponse = zod.object({
  "response": zod.string(),
  "timestamp": zod.string(),
  "suggestedQuestions": zod.array(zod.string()).optional()
})


/**
 * @summary AI reorder quantity suggestions
 */
export const GetReorderSuggestionsResponseItem = zod.object({
  "productId": zod.number(),
  "productName": zod.string(),
  "sku": zod.string().optional(),
  "currentStock": zod.number(),
  "reorderPoint": zod.number().optional(),
  "suggestedQuantity": zod.number(),
  "estimatedCost": zod.number(),
  "urgency": zod.enum(['low', 'medium', 'high', 'critical']).optional(),
  "preferredSupplierId": zod.number().nullish(),
  "preferredSupplierName": zod.string().nullish()
})
export const GetReorderSuggestionsResponse = zod.array(GetReorderSuggestionsResponseItem)


